import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse(`{"title":"External links at a glance","description":"Review all of a Space's outward-facing access points in one place.","frontmatter":{"title":"External links at a glance","description":"Review all of a Space's outward-facing access points in one place."},"headers":[],"relativePath":"en/zusammenarbeit/externe-links.md","filePath":"en/zusammenarbeit/externe-links.md","lastUpdated":1787319236000}`),i={name:"en/zusammenarbeit/externe-links.md"};function o(s,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="external-links-at-a-glance" tabindex="-1">External links at a glance <a class="header-anchor" href="#external-links-at-a-glance" aria-label="Permalink to &quot;External links at a glance&quot;">​</a></h1><p>Under <strong>Space settings → Links</strong>, you&#39;ll find all external access points of a Space:</p><blockquote><p><em>Here&#39;s a list of all external links in this Space</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">The most important page for an overview</p><p>This is the <strong>only</strong> place where all outward-facing access points are collected in one view. Form links originate in the form, portal links on the page, webhook addresses in the Flow — here they all come together.</p><p>Anyone who wants to know what&#39;s reachable from outside checks here.</p></div><h2 id="link-types" tabindex="-1">Link types <a class="header-anchor" href="#link-types" aria-label="Permalink to &quot;Link types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th><th>Created in</th></tr></thead><tbody><tr><td><strong>Add entry</strong></td><td>Form link for creating</td><td><a href="/en/formulare/formular-teilen">Sharing a form</a></td></tr><tr><td><strong>Edit entry</strong></td><td>Form link for editing</td><td><a href="/en/formulare/eintraege-bearbeiten">Editing entries via a form</a></td></tr><tr><td><strong>Page</strong></td><td>Portal link</td><td><a href="/en/seiten/portal-veroeffentlichen">Publishing a portal</a></td></tr><tr><td><strong>Start Flow</strong></td><td>Webhook address</td><td><a href="/en/flows/webhook-trigger">Starting a Flow via webhook</a></td></tr><tr><td><strong>Flow execution</strong></td><td>Link to a running instance</td><td><a href="/en/flows/seiten-in-flows">Pages in Flows</a></td></tr><tr><td><strong>Space invitation</strong></td><td>Invitation link</td><td><a href="/en/zusammenarbeit/personen-einladen">Inviting people</a></td></tr></tbody></table><p>Links without a name appear as <strong>Unnamed</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Name your links</p><p>If you create several links to the same form via <em>Add link</em>, give them descriptive names — &quot;Newsletter&quot;, &quot;Trade show booth&quot;, &quot;Website&quot;. Otherwise you end up with five entries here and no one remembers what&#39;s what.</p></div><h2 id="why-review-this-regularly" tabindex="-1">Why review this regularly <a class="header-anchor" href="#why-review-this-regularly" aria-label="Permalink to &quot;Why review this regularly&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">A link stays active until it&#39;s removed</p><p>Shared links don&#39;t expire. They keep working:</p><ul><li>after the project is finished</li><li>after the campaign has ended</li><li>after the person has left the company</li><li>after the connecting service has been shut down</li></ul><p>No one will notify you. Only this list shows what&#39;s still open.</p></div><p>A good occasion for a review:</p><table tabindex="0"><thead><tr><th>Occasion</th><th>What to check</th></tr></thead><tbody><tr><td><strong>Project completed</strong></td><td>Portals and forms for the project</td></tr><tr><td><strong>Campaign ended</strong></td><td>The related named form links</td></tr><tr><td><strong>Personnel change</strong></td><td>Everything that person created or received</td></tr><tr><td><strong>Outside system shut down</strong></td><td>Webhook addresses of type <em>Start Flow</em></td></tr><tr><td><strong>Regularly, e.g. quarterly</strong></td><td>Everything</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Especially important after a personnel change</p><p>Removing a person from the Space only ends their <strong>Space access</strong>. Links they created or received keep working — for them too.</p><p>→ <a href="/en/zusammenarbeit/personen-einladen">Inviting people</a></p></div><h2 id="removing-a-link" tabindex="-1">Removing a link <a class="header-anchor" href="#removing-a-link" aria-label="Permalink to &quot;Removing a link&quot;">​</a></h2><p>Via the list. A removed link stops working <strong>immediately</strong> — even for people who have it saved or currently have it open.</p><div class="danger custom-block"><p class="custom-block-title">Printed codes and embedded portals</p><p>A QR code on a poster or a portal embedded in an outside website can&#39;t be recalled. Both point into empty space once the link is removed.</p><p>Check where a link is in circulation before deleting it. For printed material, a dedicated, permanent link is worth setting up.</p></div><p>Entries already submitted remain intact, of course.</p><h2 id="restricting-access-instead-of-removing" tabindex="-1">Restricting access instead of removing <a class="header-anchor" href="#restricting-access-instead-of-removing" aria-label="Permalink to &quot;Restricting access instead of removing&quot;">​</a></h2><p>Instead of deleting a link, you can restrict it:</p><table tabindex="0"><thead><tr><th>What you&#39;re sharing</th><th>Options</th></tr></thead><tbody><tr><td><strong>Form</strong></td><td><em>Anyone</em> / <em>Any registered user</em> / <em>Anyone in this Space</em></td></tr><tr><td><strong>View or portal</strong></td><td><em>Everyone</em> / <em>With credentials</em></td></tr></tbody></table><p>→ <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></p><h2 id="what-the-list-doesn-t-show" tabindex="-1">What the list doesn&#39;t show <a class="header-anchor" href="#what-the-list-doesn-t-show" aria-label="Permalink to &quot;What the list doesn&#39;t show&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Two limitations</p><ul><li><strong>It&#39;s limited to one Space.</strong> With multiple Spaces, you need to check each one individually.</li><li><strong>The display can be filtered.</strong> Depending on the setting, not all technical link types are visible. For a complete inventory of sensitive access points, also review the share dialogs of individual forms, views, and pages.</li></ul></div><h2 id="number-of-links" tabindex="-1">Number of links <a class="header-anchor" href="#number-of-links" aria-label="Permalink to &quot;Number of links&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Plan-dependent</p><p>How many additional links you can create per form or portal depends on your plan.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li><li><a href="/en/spaces/einstellungen">Space settings</a></li><li><a href="/en/zusammenarbeit/personen-einladen">Inviting people</a></li></ul>',27)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
